import { toTable } from "../lib/toon.js"

interface ChangelogEntry {
  version: string
  date: string
  description: string
}

const CHANGELOG: ChangelogEntry[] = [
  { version: "0.6.24", date: "2026-09-10", description: "Oracle quality. Fifth field report: a unit passed its gate while shipping a 760 KB unauthorized payload (the checkpoint asserted pins and never read the output; the re-verify ran the same blind command) and another admitted ZZ/QQ/AA as country codes with every control proven to fail when removed. Fixed in shipped code: the verdict read the current spec contract (smoke: null written after delegation lifted the gate; the attempt-frozen digest is checked first now, CONTRACT CHANGED); unknown block fields were stripped silently (strict now); digests hashed path+size past 4 MiB (complete bytes now, truncated inventories refuse); add_rejection.ts defaults to server time; a mutation that broke the build counted as a kill (invalid now). New: deliverables in the contract block (files the smoke plan must produce; min/max bytes, JSON checks, values_in against a reference file frozen at delegation); live_smoke refuses while a deliverable already exists, digests and evaluates each after the run; set_verdict pass recomputes every digest wherever a plan or deliverable is declared, in any phase. record_review must cite the newest passing live_smoke run_id of every covered unit with deliverables (smoke_receipts) and the gate refuses an uncited receipt. preflight_check creates: [{ file, tests }] declares files the unit creates; their citations are forward, frozen onto the delegation and checked at the pass verdict (FORWARD CITATIONS UNMET); -run selectors resolve with Go semantics. Not built: claim-backed value sets, an assertion algebra, adequacy scores, a Middle-rank line cap." },
  { version: "0.6.23", date: "2026-09-10", description: "contract_probe and live_smoke read the credential store. Field report on 0.6.22: the operator put the token in ~/.foreman-mcp/.env and contract_probe answered credential_missing, because it resolved ${ENV:NAME} from process.env alone; live_smoke checked its plan's env names the same way and spawned the runner with the inherited environment, so the store reached neither. Both now resolve through one function with loadForemanEnv's precedence (process env first, the store second), register every store value for redaction, name each variable's source in the output and never its value, and report a malformed store as credential_store_invalid. run_tests gained an env overlay for the child, used by live_smoke only. The worker path's endpoint guard is deliberately not applied: a probe's destination comes from the spec's contract block, the reviewed authoring place, and every record names the target and the variable names used." },
  { version: "0.6.22", date: "2026-09-10", description: "Reality as a source of truth. A fourth field report (94.6% coverage, six killed mutations, green suite, clean guard, and the unit could not complete one HTTPS request) and an architecture council that converged in three rounds. Fixed in shipped code: preflight accepted any passing probe on the unit (now every registered claim needs a passing claim-mode probe under the current contract digest); an over-cap body was hashed as a 4 MB prefix (capture streams, incomplete capture fails every body assertion); the preflight lookup ignored the phase; the preflight file was not guard-excluded; a guard comparison attached to the newest delegation (it now carries the baseline hash and is refused against a different one). New: a foreman-contract fenced block in the spec registers a unit's claims (request recipe plus assertions, json_array_length included) and its smoke plan or a reviewed smoke: null; Foreman digests it, the delegation freezes the digest, and in a has_api phase a unit with no block cannot pass preflight. contract_probe takes a claim_id and loads the recipe from the spec; url mode is diagnostic and never satisfies a claim. live_smoke takes a plan_id, runs the frozen plan through run_tests, and records a receipt bound to the attempt, the contract digest, a harness digest and an input digest; set_verdict pass in a has_api phase recomputes the digests and refuses without a current passing smoke (SMOKE REQUIRED, waivable as smoke). The ledger holds one repository window per root: a snapshot acquires it, an ok compare moves it to validation, a verdict or close_attempt releases it, and another unit's delegation or snapshot is refused meanwhile (WINDOW BUSY). Rejected: an assertion algebra, receipt expiry by clock, per-phase contracts, a scheduler." },
  { version: "0.6.21", date: "2026-09-10", description: "Third field report plus a Codex deliberation over the designs. Fixed in shipped code: the fence check never fired through repo_guard because the snapshot's own ledger write moved a mark (marks now cover the progress-state file only); the preflight lookup let an earlier pass survive a later failure and cross units (newest record decides, per unit); verify_oracle restored blindly, had no baseline and counted timeouts as kills (conflict-safe restore, per-configuration green baseline, invalid for timeouts and aborted runs, relevance hint, runs in repo root). New: close_attempt types non-failure endings (delivered, blocked, validation_only) with lifetime counters while failure evidence stays server-authored; worker heartbeats and worker_status keyed on the current attempt; phase_ownership sweeps each unit against its own files and assigns outside sites; contract_probe executes GET/HEAD itself with explicit assertions and preflight_check requires a passing probe in a has_api phase. pitboss_paths vetoed: content cannot attribute a write; the protocol serializes pit-boss doc writes around the worker window instead." },
  { version: "0.6.20", date: "2026-09-10", description: "Per-unit review coverage. The phase gate keys review currency on each unit's attempt instead of the phase's newest verdict: a record covers a unit when it was recorded at or after that unit's verdict and its snapshot names the unit's current attempt, and the gate demands coverage of every unit's current attempt by an independent record, a complete native record, or an eligible verification. REVIEW REQUIRED names the uncovered units. record_review data.units scopes a seat's snapshot to the units it examined (narrowing only), so a re-review after one test-only attempt covers that unit while the earlier seat keeps covering the rest. Confirmed findings and incomplete records on an earlier seat keep blocking while it carries a unit no later seat covers; supersession requires the re-run to cover those units. Retention protects every carrying record. The gate stamp lists every carrying seat and its basis is the weakest per-unit class (policy_version 2); escapes attribute as before through the stamp's attempt snapshot. A scoped record cannot be a verification baseline. Legacy records without a snapshot stay timestamp-keyed (whole-phase, as before), and a verification's named units count only where its eligibility blocker validated them." },
  { version: "0.6.20", date: "2026-09-10", description: "Nit path: a post-gate test-assertion nit took eight ledger/guard writes in the field (ip, add_rejection, record_escape, delegated, snapshot with the retyped file list, compare, verdict, gate); it takes four now (set_unit_status+rejection, snapshot, compare, set_verdict) plus the gate. set_unit_status s:'delegated' accepts data.rejection { r, msg, escape_class? } — add_rejection's semantics (rej[] stamp, failed-attempt count, cap, escape source 'rejection', reopen) recorded before the attempt in one write with one timestamp; any refusal of such a write says the rejection was not recorded (the write is refused whole). set_verdict accepts data.escape_class, classifying the unit's newest unclassified escape before the ESCAPE UNCLASSIFIED check (an older one, possible only after an escape_override, still refuses; ESCAPE CLASS refuses when there is none to classify). repo_guard snapshot on a correction copies allowed_files and max_entries from the from_attempt baseline when omitted (authorized_from in the output); a different explicit set is still refused by the ledger. Cuts are bookkeeping only: the guard, the attempt cap, ESCAPE UNCLASSIFIED and the gate re-pass (worker_delta or a fresh seat) are unchanged. Rejected: a one-call guard for a correction — the only stored baseline is the previous attempt's pre-worker snapshot, and between a gate pass and a nit the owner may commit (HEAD moves, the dirty set collapses into disappeared-path violations), stash or edit; only a baseline taken at the moment of delegation makes a violation attributable to that worker [CWE-345]. Rejected: requiring a rejection on every correction (a follow-up on a passing attempt records post_gate_attempt, classified on the verdict)." },
  { version: "0.6.20", date: "2026-09-10", description: "Same-worker reuse works mid-unit: a correction binds its worker_id onto the previous attempt when that attempt carries none, whatever verdict it received (same declared session, cleared guard, all other correction predicates unchanged), recorded as worker_id_bound { at: 'correction', ts, by_attempt } with a late-bound note in the warning; a recorded id is never rebound and set_verdict binding is unchanged. Pre-change delegations without session_id, from another declared session, or with a recorded id are refused exactly as before; a pre-change same-session delegation with no id and a cleared guard becomes bindable." },
  { version: "0.6.20", date: "2026-09-10", description: "repo_guard no longer charges the worker for Foreman's own writes. The excluded set is derived from one module, lib/foremanFiles.ts, which the writers also import: the five .foreman-* state files (ledger, progress, journal, events, seats) wherever they sit, their .corrupt.<ts> backups and atomic-write .tmp files (also for custom-named state files, by path), and the fenced checklist block in Docs/PROGRESS.md. PROGRESS.md is fingerprinted with the fence removed, so an edit outside the fence is still a violation, a second fence is a violation, and a user's own PROGRESS-like file elsewhere is never excused; the fence interior is not verified by the guard (the ledger is authoritative and the next write_progress overwrites it). A bare *.tmp is no longer excused, and preview_diagram output under <docsDir>/diagrams stays charged to whoever holds the window. Scope paths are canonicalised (junctions, symlinks, 8.3 names) before they are related to the repository root; the snapshot reports foreman_files and says so when the scope resolves outside the root. Baselines recorded before this release are read through the same filter and compared as before: an untouched PROGRESS.md is clean, a write_progress in the window is today's violation with the legacy cause named, and a stale seats entry cannot manufacture a disappeared-file violation. Mid-upgrade only: a bare *.tmp dirty before an old-server baseline is reported on a new-server compare of that same attempt; a new attempt clears it. Soft limits: over-long journal msg, record_review checked[]/limitations and native reviewer checked[] entries are cut with a trailing '…[truncated N chars]' marker plus a TRUNCATED warning instead of refusing the write; ids, findings, evidence and notes still refuse." },
  { version: "0.6.20", date: "2026-09-10", description: "Two field reports, eleven items. preflight_check compares a worker brief against the spec before the attempt is spent (symbols must appear in the spec, citations must resolve; omissions, contradiction markers, drifted citations and out-of-set type references are advisories) and returns a brief_hash that set_unit_status s:'delegated' requires once the project has run it. verify_oracle is the mutation primitive the protocol asked for: apply, run the guard test, restore by hash, record killed/survived/invalid on the unit. Probe check: a gap about an external system is answered by version-matched docs plus a side-effect-free probe before it can be escalated; ASK ONE LINE for side effects or a missing credential; OWNER DECISION only for policy. claude_workflows_init installs three saved Workflow scripts on Claude Code; stage:'native' opens to Claude Code under the basis stamp and the independence bound. repo_guard excludes every Foreman-written file from one module and fingerprints PROGRESS.md fence-stripped, refusing a fenced-block change with no Foreman progress write. Review staleness keys per unit. Same-worker reuse binds the worker id late. The nit path is four writes plus the gate. Soft limits truncate with a marker instead of refusing. run_tests accepts a pinned toolchain path; model ids keep their rank under a host suffix; T_BLIND; write_progress retire_unit; write_ledger record_fact and read_ledger facts." },
  { version: "0.6.19", date: "2026-09-09", description: "Review outcomes: the seat rule at the phase gate is unchanged, but every counted pass is stamped with the basis that carried it (receipted_external, declared_external, same_provider, delta variants, override), its seats, the per-unit attempt snapshot, every waiver accepted, the declared rank and a token split, with per-basis totals that survive the bounded history; read_ledger review_outcomes recomputes the table on every read. Escapes: a rejection, non-pass verdict or new attempt on a unit its gate still covers records an escape against that gate, keyed on the attempt snapshot so a pass-to-pass re-verdict cannot exit coverage; the class is a closed enum the ledger demands before the unit's next pass verdict and the phase's next counted pass (record_escape, or add_rejection escape_class). Seat receipts: invoke_advisor appends a hash-chained receipt for every run and returns seat_receipt and packet_sha256; record_review binds one receipt to one independent record after checking packet hash, success, single use and recency, and the gate basis reads receipted_external only from provenance Foreman wrote. Independence bound: three consecutive counted passes carried by same-provider review, an override, or on Codex an unreceipted independent record are the limit; the next is refused until a receipted cross-vendor seat resets the streak or the owner overrides on the record. Worker-delta records gain structural bounds (fresh verifier against baseline native agents and every worker in the phase; checked covers evidence.files; at most two verification records per baseline on a server scalar) while the Top-only admission is unchanged. invoke_council writes one receipt per seat with the vendor from a prefix allowlist else unknown, which is never external. review_outcomes ends with owner-review triggers T1-T4 and scripts/review-outcomes.mjs renders the table across N ledgers. Review predicates moved to reviewPredicates.ts unchanged. A 19-agent deliberation rejected a rank-weighted review scheme: Foreman has no source for the model a native reviewer ran on, so rank never enters review sufficiency." },
  { version: "0.6.18", date: "2026-09-09", description: "Declared workflow rank. The pit-boss reports model and reasoning effort at init_session or via write_journal declare_model; Foreman resolves a rank from an explicit allowlist of host-emitted ids (claude-fable-5-1, claude-opus-5, gpt-6-astra at high+ effort, ...) and display names, and unknown ids stay on the normal protocol. Middle rank permits same-worker mechanical corrections with a compact follow-up; Top rank additionally permits bounded fixes, focused intermediate validation, and a worker_delta verification by a verifier distinct from every correcting worker. Every correction is a new recorded attempt bound to the same worker_id and journal session, inside the previous frozen authorized file set, with a cleared ownership guard; hot_path and security_boundary phases are excluded. Seat reviews snapshot per-unit attempt counts, so a review is current only when no unit has a newer attempt. Direct Fix is legacy-only: the pit-boss never writes code, fixes, or tests. Rank is a trusted self-declaration by design; it never changes agent_class, seat capability, or cost tier, and never waives workers, guards, or checkpoint gates. Reconciles 0.6.13 with 0.6.16: a same-model fan never counted as a seat; a complete native review with distinct reviewers, lenses, and a separate verifier now satisfies the Codex gate as labelled same-provider review." },
  { version: "0.6.17", date: "2026-09-09", description: "All host profiles share the same ledger-derived state in read_progress and session_orient, including passed/remaining units and phase gates. Checklist totals are labeled separately and no longer claim project completion or choose a competing next unit. Declared units count toward remaining work, and progress reads leave corrupt files untouched." },
  { version: "0.6.16", date: "2026-09-09", description: "Codex defaults to native workers, distinct risk-lens reviewers and a separate verifier. Complete stage:'native' evidence satisfies its phase gate without external CLIs or an override; stale reviews, incomplete coverage and confirmed findings remain blocking. Major checkpoints add available Claude/Gemini advisors through existing tools; missing optional providers do not block native review. Native provenance is recorded as same-provider review. Host procedures, diagnostics, role instructions and MCP validation support the native path; legacy fan records and other hosts retain their gate policy." },
  { version: "0.6.15", date: "2026-09-09", description: "Codex host only: the pit-boss picks an implementation seat per unit instead of one seat for everything. codex_agents_init writes worker_light, worker and worker_heavy alongside the existing roles, each pinned to a model verified by live probe on codex-cli 0.153.4 — gpt-5.6-terra, gpt-5.6-sol, gpt-6-astra. The version is load-bearing: gpt-6-terra and gpt-6-sol are both refused on a ChatGPT account, so a family is not portable across a version bump; CODEX_SEAT_MODELS is the single source and the models input still overrides per role. The worker_invoke text maps the seat to Foreman's existing cost tiers (cheap/standard/premium, already recorded on every delegation with a route_reason): light for a fully specified edit, standard as the default for ordinary implementation and for anything unclassifiable, heavy for concurrency, migrations, error semantics, public contracts, security paths, or a unit a lower seat already failed. Escalation stays evidence-bound to the existing rule — a fix worker moves up only when route_reason cites the rejection, a refined brief, or an advisor diagnosis, never a blind bump. The unverified gpt-5.6-luna reference is gone from both the invoke and fan-out text. Reasoning effort is not pinnable per role in this build, so the text says to pass it at spawn time (high for light and standard, xhigh for heavy) and never to assert an effort the host did not apply. host_status reports the Codex seat table instead of a slug scraped from prose. claude-code, cursor and generic are untouched." },
  { version: "0.6.14", date: "2026-09-09", description: "Compressed tool output is checked for the literals a verdict depends on. run_tests and invoke_advisor output is compressed before the pit-boss reads it, and the pit-boss reads the failing file:line and the exit code out of that text — but the only guard was that a retrieval marker survived and the output was non-empty, so a digest could drop every location in a failure report and still be served. A protected-literal check now compares original against served text: a critical literal lost entirely, or invented from nothing, discards the digest and serves the original (the rejection reason goes to stderr). Which classes gate was set by measurement, not taste: compressing this repo's own 5,000-line fixture keeps 4 of 4 paths and drops 103 of 103 incidental timings, so locations, paths and the exit code gate while bulk noise does not, and a repeated literal deduplicated to a lower non-zero count is allowed. The check runs on the text actually served, after the meta head is re-prepended. File extensions must start with a letter so an address like 127.0.0.1:5432 is not mistaken for a source location." },
  { version: "0.6.13", date: "2026-09-09", description: "Codex host only: the advisor-review last rung is now a review fan on Codex's own subagents instead of two self-review passes in the pit-boss seat. codex_agents_init gains read-only `reviewer` and `verifier` roles (no writes, no further spawns, no ledger verdicts). The pit-boss spawns one reviewer per risk lens — 3-5 from the versioned catalog, in parallel under agents.max_threads, each seeing only its lens question and never another reviewer's output — then one verifier that opens every cited file:line, classifies confirmed/rejected/unverified, re-rates severity by blast radius, merges duplicates, and returns the single report the orchestrator sees. record_review accepts stage:'fan', stored with findings, checked, and a limitations note naming the unavailable CLIs. A fan is PERSPECTIVE, not independence: separate contexts and one lens each remove shared reasoning but leave one model's blind spots correlated, so like cross_exam it never counts as a seat for the phase gate, and the REVIEW REQUIRED message names it and points at the owner's decision. A confirmed finding in a fan still blocks the gate. max_depth=1 throughout." },
  { version: "0.6.12", date: "2026-09-09", description: "repo_guard was unusable on any repository larger than this one. The index fingerprints came from an unscoped `git ls-files -s`, whose output is a row per TRACKED FILE and so scales with repository size rather than with the change being compared; it measured 13 KB against the 16 KB capture limit here, passed every test, and refused every snapshot in the field with 'output exceeded the capture limit'. The call is now scoped to the changed paths and batched by argument length. The changed-path limit is a generous default the caller can raise instead of a wall: max_entries on snapshot defaults to 500, ceiling 5000, and compare reuses the baseline's value; git output budgets are sized from that limit (runExternalCli takes an optional maxStdout, ceiling 2 MB, default unchanged at 16 KB for advisor and test output). A truncation now says how to resolve it. Regression test: a repository whose full index exceeds the capture limit snapshots correctly with a one-file change." },
  { version: "0.6.11", date: "2026-09-08", description: "repo_guard rework after an adversarial review of 0.6.10 reproduced nine defects in it. The headline one: the comparison diffed PATH SETS, so a file already dirty before the worker ran stayed dirty afterwards and overwriting the user's uncommitted work returned ok — the exact loss the guard exists to prevent. Every changed path now carries a content fingerprint for the work tree and the index, so a change to an already-dirty file is visible. Every git probe is checked for exit status, timeout, and output truncation; a failed probe is a refusal and is never read as a clean tree (a corrupt index previously reported an empty, clean snapshot). The baseline and the authorized file set are frozen at snapshot time: a second baseline for the same attempt is refused, and compare no longer accepts allowed_files, closing two paths by which the model could retry until the guard turned green. Status is read NUL-delimited with -uall and core.quotepath=false, so untracked directories expand to files, unicode and spaced names round-trip, and a literal ' -> ' in a filename is no longer parsed as a rename. The snapshot records the repository root, so a comparison run against a different checkout is a violation. Foreman's own state files are excluded, since the pit-boss writes them during the unit. A recorded violation now outlives its attempt (a direct fix bumped attempt_seq and dropped the block) and reopens a standing pass to pending. Truncation blocks only on real overflow, and an authorized repair that restores committed content is allowed. Entry cap 200." },
  { version: "0.6.10", date: "2026-09-08", description: "repo_guard (27th tool): the shared-tree ownership check runs in Foreman instead of being described to the model. 'snapshot' captures branch, HEAD, stash ref/count, staged and dirty paths, core.autocrlf, and git ls-files --eol before an editing worker runs, and records them on the unit's newest delegation; 'compare' re-reads them afterwards and names every mutation outside allowed_files — a moved HEAD, a touched index or stash, a changed config, a file changed outside the brief, or a pre-existing uncommitted change that disappeared. Both results are written by Foreman, so set_verdict refuses a pass whose guard did not clear (REPOSITORY GUARD; user_override records guard_override on the delegation). Previously this was two paragraphs of protocol prose the pit-boss ran by hand, holding the baseline in conversation context, where a compaction destroyed it silently and a skipped check looked exactly like a passed one. Enforcement is scoped to delegations that carry a snapshot: outside a git work tree the tool reports n/a, and older ledgers and hosts that never call it keep their existing behavior. [CWE-88] file paths are validated and passed after a -- separator so a name cannot become a git option." },
  { version: "0.6.9", date: "2026-09-08", description: "Field-feedback round 6: the paid review loop at the phase gate. A pitboss ran six review rounds on one phase because every LOW fix re-verdicted a unit, which staled the review, which demanded a fresh seat; Codex replayed the ledger and found four enforcement holes, all closed here. REVIEW REQUIRED now states whether a stage:'verification' record would satisfy the gate right now (VERIFICATION ELIGIBLE with the exact record shape, baseline ts and direct-fix attempts filled in, or VERIFICATION NOT ELIGIBLE with the single blocker). Verification predicates: the baseline must be a complete seat (a failed, partial, or silent review cannot anchor one) and every attempt since the baseline must be a direct fix (a worker delegation or invoke_worker sidecar attempt in between is refused, not only the current attempt). Review retention keeps the 20-record cap but never evicts a record the gate is blocking on (a current confirmed finding, an unsuperseded failed or silent seat) or the baseline of a current verification record. A failed, partial, or silent seat is superseded for the INCOMPLETE REVIEW check by a later complete record from the same advisor at the same stage; confirmed findings on the superseded record still block. Implementor names the hint and the re-run rule at the checkpoint." },
  { version: "0.6.8", date: "2026-09-05", description: "Codex seat runs gpt-6-astra at xhigh reasoning (codex-cli 0.153.4 or newer; 0.152.0 reports the id needs a newer CLI, other *-astra spellings are refused on a ChatGPT account). invoke_advisor reads the model and reasoning effort Codex echoes in its header, reports model_served and reasoning_effort, and treats a substituted model as a failed seat, matching the Gemini rule." },
  { version: "0.6.7", date: "2026-09-04", description: "Gemini seat pinned to gemini-3.1-pro-preview with served-model checking. 0.6.6's gemini-3.8-flash pin was accepted by the CLI but served by gemini-3.5-flash on the tested account, silently (exit 0, plausible answer); 3.7-flash the same. invoke_advisor and capability_check run gemini with --output-format json, report model_requested/model_served and thinking tokens from the run stats, and treat a served model other than the pinned one as a failed seat (model_substituted). Older CLIs printing text: model_served unknown, handled as before." },
  { version: "0.6.6", date: "2026-09-04", description: "Gemini advisor seat runs gemini-3.8-flash: invoke_advisor and capability_check pass the model id directly instead of the arch-review alias, which existed only in one machine's ~/.gemini/settings.json. Verified through the CLI (an unknown id fails with ModelNotFoundError, so the answer is not a fallback). Gitleaks allowlist restores the two aider fixture tokens that remain in history after the 0.6.3 file removal." },
  { version: "0.6.5", date: "2026-09-04", description: "Field-feedback round 5. invoke_advisor reports exit 0 with empty or echoed stdout as completion: failed with the stderr tail (no in-tool retry). session_orient state_drift fires only on a progress entry marked complete for a unit the ledger has not passed (or progress units with no ledger phases); stale/ahead/orphan entries are a non-blocking progress_advisories field, and pointer-order disagreement never blocks. authorize_attempts records one owner grant of 1-10 attempts past the cap, charged per attempt (cap_grants[], attempt_grants in orient, cap_grant in the unit view); refused below the cap, while a grant is open, or together with user_override (AMBIGUOUS OVERRIDE); a pass closes it. Review currency needs an independent review or an eligible stage:'verification' record — cross_exam never counts; council payloads carry stage: independent. stage:'verification' with evidence {baseline_review_ts, units[{unit_id, attempt}], files, tests, probe} stands in for a seat only for linked direct-fix re-verdicts on an unscoped phase with no confirmed finding above LOW since the baseline. checked[] entries up to 400 chars. complete_unit counts legacy checkbox lines outside the fence (legacy_checkbox_candidates) and never edits them." },
  { version: "0.6.4", date: "2026-09-04", description: "Field-feedback round 4. The delegation cap guards the pass, not only the delegation record: a pass needs an attempt recorded after the latest rejection or fail verdict (ATTEMPT REQUIRED) and, past the cap, user_override (recorded as cap_override); the cap counts failed attempts since the unit last passed; fail verdicts count; a Direct Fix is recorded as an attempt via set_unit_status { s:'ip', direct_fix }; counts live in server-written per-unit scalars (attempt_seq, epoch_failed, last_failed_attempt, needs_attempt) so the 20-entry array caps cannot lose them; the post-21st-delegation rejection stamp is fixed; session_orient reports attempt_blocks. record_review requires a classification on every finding (earlier unclassified reviews read as INCOMPLETE REVIEW). bundle_status compares dist/, package.json, and the stack profile override against a process-start snapshot and answers restart_recommended true/false/n/a with the reason. Journal msg (400) and review checked (50 x 200) limits named in the tool descriptions. Advisor Grounding Protocol: bounded-verification wording, refusal recorded as completion:'failed' and retried once. One-call review recording declined." },
  { version: "0.6.3", date: "2026-09-04", description: "Surface reduction. aider_worker removed (tool, worktree library, Python harness, tests); failure taxonomy 21 -> 17 active stages with a read-only legacy set so old sidecars keep their refunded classification; .foremanenv drops aider-cli and the NUM_CTX/MAX_REFLECTIONS/REASONING_TAG keys. Tarball ships only runtime files via a package.json files whitelist (dist/, src/skills/, HOST-CONTRACT.md, README, LICENSE, bundled deps); build cleans dist/ first; no declarations or source maps; a test pins the packed manifest. Publish smoke also activates a protocol, serves ethos, checks the installed file set, and runs --diag from the installed package. Journal codes trimmed to 15 (twelve never-emitted codes plus CAP_WAIVER removed; old journals still parse). Loopback regression test for a configured invoke_council seat. Default tool count 26 (27 under Codex)." },
  { version: "0.6.2", date: "2026-09-04", description: "Docs rewrite + field-feedback round 3. README and the 16-page docs site rewritten plain (actor named, enforced vs instructed separated, copy-paste prompts). Phase gate: only reviews recorded at/after the latest unit verdict count; refuses on a 'confirmed' finding (CONFIRMED FINDINGS) or an incomplete review — partial/failed, or zero findings with no checked[] (INCOMPLETE REVIEW); overrides recorded on the phase. Per-operation data shapes moved into the write tools' input schema (hosts clip descriptions at ~2,000 chars); every description held under the clip by a test. normalize_review parses bounded item blocks (bold-numbered items, Severity: mid-line or next line, — HIGH: after a location, [P0]–[P3], tables, consecutive headings). bundle_status reports running vs on-disk version and restart_recommended. Line-endings clause in the fan-out rule and host contract; aider_worker worktrees use core.autocrlf=false. run_tests: gofmt and golangci-lint allowlisted with fail_on_stdout. Journal msg limit 400. Implementor spec-amendment rule for SPEC_GAP." },
  { version: "0.6.1", date: "2026-09-03", description: "Field-feedback round 2. Schema errors from write_ledger/write_journal/write_progress are one hint per field plus the operation's expected data shape (no more raw Zod dumps). The Step 4.5 preflight is attested on the delegated write: s:'delegated' requires data.preflight { symbols_grepped, self_consistent: true, telemetry? } and stores it on the delegation entry. Journal codes SPEC_GAP (gap decided, recorded, continuing) and GATE_OVERRIDE (user forced past a checkpoint, same session kept). invoke_advisor drops stderr on success unless stdout itself was truncated (then a 40-line tail). run_tests gains opt-in strip_patterns and tail_lines output shaping." },
  { version: "0.6.0", date: "2026-09-03", description: "Field-feedback release (8 items + 3 Codex-found root causes). normalize_review parses real advisor layouts (numbered/bulleted markers in any decoration, Severity: fields, Finding N headings, trailing tokens) and never turns unmarked prose into a finding (new unparsed_lines, findings_json line, pipe-safe table). write_journal/write_ledger descriptions carry exact per-operation data shapes generated from the validation schemas and pinned by a contract test. Ledger: add_rejection on a passed unit reopens it to pending; the phase gate refuses g:'pass' with zero record_review entries (user_override recorded as review_override); set_verdict stamps first_pass_ts once; record_review gains completion/checked/limitations/stage. session_orient orders phase and unit ids naturally (p2 before p10) and reports last_completed_unit as the first-pass frontier plus additive latest_pass_verdict_unit/ts. Implementor: Direct Fix eligibility rule (literal substitutions on host-native-delegated units only), brief self-consistency + telemetry reserved-name preflight steps, checkpoint examined-list contract with partial/cross_exam staging. Spec generator: fenced machine-owned Ledger Status block + fence-free Unit Plan (no duplicate PROGRESS checklists), G10, state_tracking_policy check-ignore step (never writes .gitignore)." },
  { version: "0.5.14", date: "2026-08-08", description: "Field-feedback release — declare_phase_units makes the spec's expected unit set a ledger fact: phase gates block g:'pass' while any declared id is unregistered, session_orient resumes at the first declared-but-unseeded unit (new missing_declared_units field) instead of misreporting retry_phase_gate, declared sets are frozen behind passed gates and join the D2b gate-staleness hash, and an auditable retire path (mandatory reason, declared_log tombstones) corrects typos without manual ledger edits. The progress checklist renders declared-but-unregistered units instead of erasing them. session_orient drift detection is now bidirectional (progress marking the ledger's resume unit complete is flagged; partial progress files stay non-drift). read_ledger paged queries emit query-specific truncation recovery hints. Implementor sessions probe advisors once at init_session and record version/auth_status; checkpoints reuse the probe. The claude-code fan-out rule gained a concrete worktree parallel-edit procedure. Diagram preview: cursor-centered wheel zoom, drag pan, toolbar + keyboard shortcuts, and client-side PNG/SVG/.mmd export under the existing strict CSP." },
  { version: "0.5.13", date: "2026-08-05", description: "Production-migration hardening: shared-tree editing workers receive an explicit Git-mutation denylist, run sequentially unless isolated, and require a before/after repository-state guard with no automatic recovery; mature ledger reads are filtered, paged, cell-bounded, and refuse oversized full output; session_orient is the ledger-authoritative resume path with gate retries, timestamp-based completion order, and progress drift reporting; run_tests supports shell-free Gradle wrappers including Windows GradleWrapperMain; journal phases accept canonical string ids; repeated green-but-unobservable checkpoint blocks escalate to mutation evidence and then owner arbitration." },
  { version: "0.5.12", date: "2026-08-03", description: "Adaptive Review Council — new EXPERIMENTAL invoke_council tool runs N remote read-only seats across M risk lenses over one evidence packet in parallel, returning ledger-shaped findings for the host to moderate and the user to arbitrate. Entirely optional: with no seats configured it returns status: unavailable, names the next rung of the deliberation ladder, and Foreman behaves exactly as before. Versioned 7-lens catalog (contract, architecture, state, security, data, tests, operability); each seat sees the packet plus ONE lens card. Seats configurable from .foremanenv or the new ~/.foreman-mcp/.env operator store, home-store-wins per seat so a model swaps without editing the repo; each seat reports its source. [CWE-522] the API key resolves from the same store that supplied the endpoint, so a repo file pointing at a local box and a home store on a hosted provider cannot misdeliver a credential. [CWE-532] every qualifying home-store value is registered for redaction, closing a gap where a second credential was invisible to scrub() and the outbound secret gate. Chat transport extracted to lib/chatTransport.ts and shared byte-for-byte with invoke_worker (two-phase timeouts, byte-capped stream, closed status mapping); invoke_worker behavior unchanged. Deliberation ladder is now 5 recorded rungs; unavailable and fail both drop a rung and are never a passed review. Optional zero-dependency Langfuse tracing, off by default." },
  { version: "0.5.11", date: "2026-07-28", description: "MCP TypeScript SDK v2 migration — split server/client packages, Zod 4 Standard Schema validation, strict input contracts, top-level tool titles, validated scalar output schemas with structuredContent, modern plus legacy stdio negotiation, split-package diagnostics, wire-level protocol regression coverage, and bundled offline-installable runtime dependencies. Package inspection excludes the workspace-local .tmp npm cache. README and HOST-CONTRACT distinguish aider_worker's MCP-managed worktree from host-enforced native-worker isolation without claiming git-stash or arbitrary user-edit recovery." },
  { version: "0.5.10", date: "2026-07-13", description: "Advisor latency update — Codex reviews run gpt-5.6-sol at xhigh reasoning effort; invoke_advisor timeout budget raised (default 15 min, cap 30 min) so Sol-class thinking time is not killed mid-reasoning and misrecorded as advisor-unavailable. CI hygiene: gitleaks fixture allowlist entries + dojo snapshot path allowlist; the python-missing capability-probe test skips on hosts where python cannot be hidden from PATH." },
  { version: "0.5.7", date: "2026-07-10", description: "Native Codex host profile: Codex spawn_agent workers (gpt-5.6-luna preferred only when host-confirmed), headless Claude Fable 5 max + Gemini independent advisors, host-rendered provider-neutral review protocol, and an authoritative runtime preamble for stale skill overrides. Claude CLI versions are telemetry only. Crucible remains an optional future custom/local-model worker runner and does not own native-host pitboss context." },
  { version: "0.5.6", date: "2026-07-09", description: "Review-model update - Codex reviews now run gpt-5.6-sol at ultra reasoning effort; Cursor Advisor A uses the matching gpt-5.6-sol-ultra model slug. Added direct regression coverage for the Codex invocation arguments." },
  { version: "0.4.0", date: "2026-07-01", description: "Cost-tier telemetry + durable review records — Fusion-inspired ledger auditability. set_unit_status now accepts optional tier ('cheap'|'standard'|'premium') + route_reason, recorded on the delegated transition and appended to a new per-unit append-only delegations[] history (survives the brief overwrite on fix re-delegation; attempt numbers stay monotonic across a 20-entry cap). A new record_review write op persists advisor findings (severity/file/line/description/classification) to Phase.reviews[] at checkpoints; read_ledger gains a 'reviews' query and the verdicts view adds a tier column. ReviewFinding is consolidated into types.ts (shared with normalize_review). The implementor protocol records tier on delegation and adds a guarded tier-escalation rule — a fix worker escalates to a higher tier only when route_reason cites a refined brief or an advisor diagnosis, never a blind bump. applyOperation gained an exhaustiveness guard so an unhandled operation throws instead of silently no-opping. All new fields are additive/optional — backward-compatible with pre-0.4.0 ledgers; no ledger schema-version bump." },
  { version: "0.3.0", date: "2026-06-13", description: "preview_diagram (23rd tool) — live, in-project Mermaid workshop. Writes Docs/diagrams/<id>.mmd (the versioned source of truth) and serves an auto-refreshing browser preview over SSE; mermaid renders client-side from a vendored bundle (no Chromium), fully offline. This is Foreman's first network listener — loopback-only (127.0.0.1), per-session token-gated, and Host/Origin-validated against DNS rebinding (no CORS headers). design-partner, spec-man, and lighttask opt in to show data flows / architecture live instead of dumping ASCII or raw Mermaid text. architecture-beta and mindmap diagram types are unsupported under the strict no-unsafe-eval render policy." },
  { version: "0.2.2", date: "2026-06-13", description: "Advisor compression fix. Successful invoke_advisor output (prose) is no longer lossy-compressed — it passed through the log compressor when a review quoted >=3 error lines, silently dropping the recommendations. Successful advisor output now passes through; only FAILED advisor diagnostics are compressed (recoverable via retrieve_original). The redundant advisor STDERR (CLI banner + echoed prompt + a duplicate of STDOUT + token count) is trimmed on clean success, with the token count preserved as a tokens_used meta line. Fixed a meta-head duplication in compressed run_tests output. retrieve_original and invoke_advisor descriptions now cue agents to retrieve the original when a compressed summary is insufficient." },
  { version: "0.2.1", date: "2026-06-12", description: "Compression pilot fix #1 — compressed run_tests/invoke_advisor output now retains the tool's leading meta block (exit_code, passed, timed_out, truncated / cli) by re-prepending it onto the compressed digest. Previously the log compressor's error-extraction dropped these lines, costing agents at-a-glance pass/fail status. Never applied to smart_crusher (JSON) output; skipped when the digest already contains the block." },
  { version: "0.2.0", date: "2026-06-12", description: "Compression pilot — context-crush integration. run_tests and invoke_advisor outputs >=2048 bytes that detect as log/diff/json are compressed with reversible CCR storage; compressed output carries a <<ccr:HASH>> marker and the new retrieve_original tool (22nd tool) exchanges the hash for the exact original. DEFAULT ON for the pilot; kill switch FOREMAN_COMPRESSION=0; per-tool allowlist FOREMAN_COMPRESSION_TOOLS (default run_tests,invoke_advisor); TTL via CONTEXT_CRUSH_CCR_TTL_SECONDS (default 300s). Prose/text outputs pass through unchanged (detect_passthrough); originals are always stored before lossy output escapes (fail-open). context-crush ships as a bundled dependency so the packed tarball is self-contained." },
  { version: "0.1.3", date: "2026-06-09", description: "Ledger invariant enforcement — protocol prose and mechanical enforcement re-synced. The delegated step (ip -> delegated -> pass) is now documented in the implementor protocol and write_ledger tool description (previously every first pass verdict hit VERDICT BLOCKED and the model learned the sequence from the error). update_phase_gate g:'pass' is blocked unless every unit in the phase has a pass verdict; empty phases cannot pass a gate. Pass verdicts on phases scoped has_tests:false or has_build:false mechanically require an attestation note. set_phase_scope's test-file mismatch warning now surfaces in the tool result, not just stderr. Read paths (read_ledger, session_orient, write_progress) report ledger_corrupt instead of silently treating a corrupt ledger as a fresh project, and never rename the corrupt file; writes warn with the .corrupt backup path. read_ledger single-unit and verdicts views now include via and note." },
  { version: "0.1.2", date: "2026-06-08", description: "Citation verification and codex CLI lookup fix. Adds verify_citations - a deterministic tool that re-reads [OBSERVED]/[IMPLEMENTED] file:line evidence and reports CONFIRMED/DRIFTED/MISSING/UNANCHORED - plus a shared citation-verification protocol gate in spec-man and doc-man (completion requires every claim-bearing ref CONFIRMED or explicitly downgraded). Fixes capability_check reporting an authenticated codex as auth_status: expired (codex health now uses 'codex login status' instead of a full codex exec with a stale model under a 15s timeout). Codex advisor now runs gpt-5.5 at high reasoning effort; Cursor advisor slug is gpt-5.5-high. Backward compatible: existing unanchored citations remain valid." },
  { version: "0.1.1", date: "2026-06-08", description: "Tool metadata release - activation descriptions now telegraph spec-man stale-plan re-evaluation, Atlas/Graphify code-surfacing, Plan Delta Ladder promotion boundaries, lighttask escalation, and optional LangGraph-style runtime-control triggers for branching multi-session workflows." },
  { version: "0.1.0", date: "2026-06-06", description: "First minor release for the lighttask/spec/doc protocol family - promotes surgical-task, spec-man, and doc-man tool heads; adds optional Graphify-backed project atlas guidance for spec-man grounding and lighttask re-evaluation on stale resume context." },
  { version: "0.0.10", date: "2026-06-06", description: "Lighttask/spec/doc protocol release - adds lighttask, spec_man, and doc_man skill activation tools; introduces surgical-task gates for workspace classification, git context, spec freshness, grounding, bypass waivers, and adversarial review; adds grounded spec/documentation protocols and deterministic capability-check tests." },
  { version: "0.0.9", date: "2026-05-06", description: "CI hygiene + semver fix — release workflow packs into release-pkg/ (gitignored) instead of the committed artifacts/ archive, so the GitHub Release attachment ships only the current version's tarball. README install URL switched to the Release download URL. Version bump skips 0.0.8.1 (npm rejects 4-segment versions). No runtime changes." },
  { version: "0.0.8", date: "2026-05-06", description: "Cursor host mode — host-aware skill rendering via placeholders (worker_invoke, advisor_a, advisor_b); --host CLI flag and FOREMAN_HOST env var (claude-code default, cursor, codex); host_status tool; capability_check returns synthetic available in cursor mode (Task subagents). Default behavior unchanged for Claude Code / Codex CLI users." },
  { version: "0.0.7.5", date: "2026-04-17", description: "Workflow hygiene patch: ledger honesty (via field, phase scope), session_orient tool, PROGRESS.md fenced auto-sync, skill trim ~30% via common protocol extraction" },
  { version: "0.0.7", date: "2026-04-11", description: "Pentest triage fixes — remove npx from run_tests allowlist + deny via env (INJ-008), regex filter on FOREMAN_TEST_ALLOWLIST (INJ-007), settled guard on runTests data handlers (EXH-004), ComSpec via SystemRoot (INJ-006), block format for invoke_advisor output (INJ-009)" },
  { version: "0.0.6", date: "2026-04-11", description: "Security hardening, cross-platform CLI invoker, session journal — input length caps on all inline schemas, normalize_review schema extraction, error_log FIFO cap, cross-platform invoke_advisor tool (SpawnPlan + stdin delivery + .cmd shim wrapping + CRLF handling), capabilityCheck adopts SpawnPlan, runTests rejects .cmd runners on Windows, session journal for operational telemetry" },
  { version: "0.0.5", date: "2026-04-09", description: "run_tests tool — bounded test output with command allowlist; externalCli buffer cap; security hardening: input length caps, rejection array cap, absolute CLI path resolution, generic skill loader errors (pentest triage v0.0.5)" },
  { version: "0.0.4", date: "2026-04-08", description: "Skill activation tools — design_partner, spec_generator, pitboss_implementor pipe skill protocols into LLM context as tools; skill:// resources kept for backward compatibility" },
  { version: "0.0.3-3", date: "2026-04-07", description: "Pitboss enforcement gate — set_verdict(pass) blocked without prior delegation; delegation requires worker brief (min 20 chars)" },
  { version: "0.0.3-2", date: "2026-04-07", description: "session_hint enforces pitboss/worker pattern — workflow directive tells remote sessions to read implementor skill and deliberate with Codex CLI" },
  { version: "0.0.3-1", date: "2026-04-06", description: "session_hint in read_progress output — actionable directive for LLM session start" },
  { version: "0.0.3", date: "2026-04-05", description: "Tool schema enums for write_ledger/write_progress operations, design-partner YIELD directives for interactive pause" },
  { version: "0.0.2.1", date: "2026-04-04", description: "DX fix — document valid operations in write_ledger/write_progress tool descriptions, fix server version mismatch" },
  { version: "0.0.2", date: "2026-04-04", description: "MCP skill delivery — design-partner, spec-generator, implementor as MCP resources; AB test validated against native skills" },
  { version: "0.0.1", date: "2026-04-02", description: "Initial architecture remediation — ledger, progress, external CLI" },
]

export function changelog(sinceVersion?: string): string {
  let entries = CHANGELOG
  if (sinceVersion) {
    const idx = CHANGELOG.findIndex(e => e.version === sinceVersion)
    entries = idx >= 0 ? CHANGELOG.slice(0, idx) : CHANGELOG
  }
  return toTable(["version", "date", "description"], entries.map(e => [e.version, e.date, e.description]))
}
